<?php require 'config/database.php';require 'config/app.php';$found=null;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$code=strtoupper(trim($_POST['code']??''));$email=strtolower(trim($_POST['email']??''));$s=$pdo->prepare("SELECT r.*,t.name AS tournament_name,p.status AS pay_status FROM registrations r JOIN players pl ON pl.player_id=r.player_id JOIN tournaments t ON t.tournament_id=r.tournament_id LEFT JOIN payments p ON p.registration_id=r.registration_id WHERE r.registration_code=? AND pl.email=?");$s->execute([$code,$email]);$found=$s->fetch();if(!$found)$error='No entry matched that registration ID and account email.';}$pageTitle='Track your entry';require 'includes/header.php';?>
<section class="page-hero compact"><div class="eyebrow">NO GUESSWORK. JUST YOUR STATUS.</div><h1>TRACK YOUR <span>ENTRY.</span></h1><p>Use your registration ID and account email to find your entry.</p></section><div class="box lookup"><div class="eyebrow">REGISTRATION LOOKUP</div><h2>Where does your entry stand?</h2><?php if($error):?><div class="alert alert-warning"><?=e($error)?></div><?php endif;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Registration ID<input name="code" required placeholder="BA-XXXXXXXX" value="<?=e($_POST['code']??'')?>"></label><label>Account email<input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></label><button class="btn btn-hot btn-lg">Check status ↗</button></form><?php if($found):?><div class="lookup-result"><div><div class="eyebrow">MATCH FOUND</div><h3><?=e($found['team_name'])?></h3><p><?=e($found['tournament_name'])?></p><span class="chip"><?=e(str_replace('_',' ',$found['status']))?></span><span class="chip"><?=e(str_replace('_',' ',$found['pay_status']??'unpaid'))?></span></div></div><?php endif;?></div><?php require 'includes/footer.php';?>
